select jsonb_pretty(jsonb_build_object('supautils_settings', (select coalesce(jsonb_object_agg(name, setting), '{}') from pg_settings where name like 'supautils.%'), 'objects_acl', (select c.relacl::text from pg_class c where c.oid = to_regclass('storage.objects')), 'postgres_member_of_privileged', pg_has_role('postgres', 'supabase_privileged_role', 'USAGE'), 'existing_storage_policies_owner_hint', (select coalesce(jsonb_agg(distinct p.policyname), '[]') from pg_policies p where p.schemaname = 'storage'))) as details;
